# -*- coding: utf-8 -*-
"""Shared helpers for IQA method implementations."""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional

PLUGIN_DIR = Path(__file__).resolve().parent.parent      # algorithm_plugins/iqa
REPO_ROOT = PLUGIN_DIR.parent.parent                     # .../algo_agent


def ensure_plugin_importable() -> None:
    for p in (str(REPO_ROOT), str(PLUGIN_DIR.parent)):
        if p not in sys.path:
            sys.path.insert(0, p)


def plugin_config():
    ensure_plugin_importable()
    from algorithm_plugins.iqa import config as C
    return C


def load_rows(path: Path | str) -> List[Dict[str, Any]]:
    p = Path(path)
    if not p.exists():
        return []
    return [json.loads(l) for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]


def load_dev(data_dir: Path) -> List[Dict[str, Any]]:
    return load_rows(Path(data_dir) / "dev.jsonl")


def load_dev_split(data_dir: Path) -> Dict[str, Any]:
    p = Path(data_dir) / "dev_split.json"
    if p.exists():
        return json.loads(p.read_text(encoding="utf-8"))
    return {}


def load_eval_inputs(data_dir: Path) -> List[Dict[str, Any]]:
    for name in ("eval_inputs.jsonl", "eval.jsonl"):
        p = Path(data_dir) / name
        if p.exists():
            rows = load_rows(p)
            return [{"path": r.get("path"), "image": r.get("image")} for r in rows]
    raise FileNotFoundError(f"no eval inputs in {data_dir}")


def defect_vector(row: Dict[str, Any], defects) -> List[int]:
    return [int(bool((row.get("defects") or {}).get(d, {}).get("present", 0))) for d in defects]


def defect_severity(row: Dict[str, Any], defects) -> List[float]:
    return [float((row.get("defects") or {}).get(d, {}).get("severity", 0) or 0) for d in defects]


def make_pred(path: str, score: Optional[float], defects: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    return {"path": path, "image": Path(path).name,
            "score": (None if score is None else round(float(score), 3)),
            "defects": defects}


def write_preds(ctx, rows: List[Dict[str, Any]]) -> str:
    out_dir = Path(ctx.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(rows, ensure_ascii=False, indent=2)
    (out_dir / "pred_test.json").write_text(payload, encoding="utf-8")
    (out_dir / f"pred_{getattr(ctx, 'split', 'test')}.json").write_text(payload, encoding="utf-8")
    return str(out_dir / "pred_test.json")


def resolve_device(prefer_gpu: bool = True):
    """Return a torch device, or None when torch/CUDA is unavailable."""
    try:
        import torch
    except Exception:
        return None
    if prefer_gpu and torch.cuda.is_available():
        return torch.device("cuda")
    return torch.device("cpu")


def all_negative(defects) -> Dict[str, Dict[str, Any]]:
    out = {d: {"present": 0, "severity": 0} for d in defects}
    out["white_balance"]["direction"] = "neutral"
    return out


def cache_dir(ctx) -> str:
    """Per-task feature/measure cache directory (off the release, reusable)."""
    d = Path(getattr(ctx, "task_root", Path.cwd())) / ".iqa_cache"
    d.mkdir(parents=True, exist_ok=True)
    return str(d)


__all__ = ["cache_dir", "plugin_config", "load_rows", "load_dev", "load_dev_split", "load_eval_inputs",
           "defect_vector", "defect_severity", "make_pred", "write_preds", "resolve_device",
           "all_negative", "REPO_ROOT", "PLUGIN_DIR"]

# -*- coding: utf-8 -*-
"""IQA domain configuration for the algo_agent business plugin.

Single source of truth for the light dual-output IQA task: the defect taxonomy,
the acceptance floors, the ROM budget and the resolution of the real local
assets (frozen benchmark, pretrained MobileCLIP2-S0 / trained adapter).

The parent workspace (``.../QAA``) holds the real IQA material produced by the
``iqa_agent`` research engine.  Everything resolves local-first with an env
override (``QAA_ROOT``) so the plugin also runs when the workspace is moved.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any, Dict, List

# ---- defect taxonomy (from the IQA requirement report) --------------------
DEFECTS: List[str] = ["blur", "over_exp", "under_exp", "flare", "white_balance"]
DEFECT_ZH: Dict[str, str] = {
    "blur": "模糊", "over_exp": "过曝", "under_exp": "欠曝",
    "flare": "炫光", "white_balance": "白平衡",
}
SEVERITY: Dict[int, str] = {0: "none", 1: "light", 2: "medium", 3: "heavy"}
WB_DIRECTIONS: List[str] = ["cool", "warm", "green", "magenta"]

# ---- acceptance floors (report ch.4 / ch.10) ------------------------------
ROM_BUDGET_MB: float = float(os.environ.get("ROM_BUDGET_MB", 60.0))
SCORE_PLCC_FLOOR: float = 0.90
SCORE_SRCC_FLOOR: float = 0.90
DEFECT_MACROF1_FLOOR: float = 0.85
HARDCASE_F1_FLOOR: float = 0.85
GRADE_AGREEMENT_FLOOR: float = 0.90
DEPLOY_PARAMS_MILLIONS: float = float(os.environ.get("DEPLOY_PARAMS_MILLIONS", 11.46))

# ---- real-MOS (KonIQ-10k) track floors ------------------------------------
# The requirement report's PLCC/SRCC target is defined against *real* human MOS
# (the trained adapter reproduced KonIQ val PLCC 0.909 / test 0.818 there).  On
# that quality-only track the defect F1 / hardcase / grade gates do not apply
# (KonIQ ships no defect annotations), so the acceptance floors are the two
# rank-correlation metrics the user asked for.
QUALITY_PLCC_FLOOR: float = float(os.environ.get("IQA_QUALITY_PLCC_FLOOR", 0.85))
QUALITY_SRCC_FLOOR: float = float(os.environ.get("IQA_QUALITY_SRCC_FLOOR", 0.85))

# A defect class needs at least this many ground-truth positives on the frozen
# eval split to be *measurable*; below it the class F1 is undefined (the
# convention below scores 0) and the all-class macro is structurally capped.
MIN_CLASS_SUPPORT: int = 5

# score -> grade bucket for the 分档一致率 (grade agreement) metric
GRADE_BINS = [(85.0, "excellent"), (70.0, "good"), (50.0, "fair"), (0.0, "poor")]

# ---- workspace / asset resolution -----------------------------------------
PLUGIN_DIR = Path(__file__).resolve().parent
REPO_ROOT = PLUGIN_DIR.parent.parent            # .../algo_agent
_WORKSPACE_DEFAULT = REPO_ROOT.parent           # .../QAA


def qaa_root() -> Path:
    """Parent workspace that holds the real IQA assets (env-overridable)."""
    return Path(os.environ.get("QAA_ROOT", str(_WORKSPACE_DEFAULT)))


def iqa_agent_dir() -> Path:
    return qaa_root() / "iqa_agent"


def benchmark_dir() -> Path:
    return iqa_agent_dir() / "_work" / "benchmark"


def registry_dir() -> Path:
    return iqa_agent_dir() / "_work" / "registry"


def dev_jsonl() -> Path:
    return benchmark_dir() / "dev.jsonl"


def eval_jsonl() -> Path:
    return benchmark_dir() / "eval.jsonl"


def measure_thresholds_path() -> Path:
    return registry_dir() / "measure_thresholds.json"


def baseline_report_path() -> Path:
    return registry_dir() / "baseline.json"


def _first_existing(*candidates: Path) -> Path:
    for c in candidates:
        if Path(c).exists():
            return Path(c)
    return Path(candidates[0])


def pretrained_ckpt() -> Path:
    """MobileCLIP2-S0 open_clip pretrained weights (encoder backbone)."""
    return _first_existing(
        iqa_agent_dir() / "models" / "mobileclip2_s0.pt",
        qaa_root() / "chuanyin_mobileclip2_final" / "runs" / "mobileclip2_s0.pt",
    )


def adapter_ckpt() -> Path:
    """Trained single-task IQA adapter (KONIQ-trained score head)."""
    return _first_existing(
        iqa_agent_dir() / "models" / "iqa_adapter_v7" / "best.pt",
        qaa_root() / "chuanyin_mobileclip2_final" / "runs" / "iqa_adapter_v7" / "best.pt",
    )


# Calibrated measurement thresholds (F1-maximising on dev). Shipping the values
# here keeps the plugin runnable even when the parent workspace is absent.
DEFAULT_MEASURE_THRESHOLDS: Dict[str, Dict[str, Any]] = {
    "blur": {"feature": "laplacian_var", "direction": "lt", "threshold": 492.852},
    "over_exp": {"feature": "over_ratio", "direction": "gt", "threshold": 0.04857},
    "under_exp": {"feature": "mean_lum", "direction": "lt", "threshold": 63.398},
    "flare": {"feature": "largest_blob_ratio", "direction": "gt", "threshold": 0.193904},
    "white_balance": {"feature": "cast_mag", "direction": "gt", "threshold": 0.5479},
}


def measure_thresholds() -> Dict[str, Dict[str, Any]]:
    thr = {k: dict(v) for k, v in DEFAULT_MEASURE_THRESHOLDS.items()}
    path = measure_thresholds_path()
    try:
        import json
        cal = json.loads(path.read_text(encoding="utf-8"))
        for d, v in cal.items():
            if d in thr and isinstance(v, dict) and "threshold" in v:
                thr[d] = {"feature": v.get("feature", thr[d]["feature"]),
                          "direction": v.get("direction", thr[d]["direction"]),
                          "threshold": float(v["threshold"])}
    except Exception:
        pass
    return thr


def rom_estimate(params_millions: float, budget_mb: float | None = None) -> Dict[str, Any]:
    """fp16 ROM estimate identical to iqa_agent.tools.budget.check."""
    budget = ROM_BUDGET_MB if budget_mb is None else budget_mb
    mb = float(params_millions) * 2.0
    return {"ok": bool(mb < budget), "rom_mb": round(mb, 2), "budget_mb": budget,
            "headroom_mb": round(budget - mb, 2), "basis": "params_fp16_estimate"}

# -*- coding: utf-8 -*-
"""Dataset export for the IQA plugin.

Turns the *frozen* IQA benchmark produced by the ``iqa_agent`` research engine
into an immutable task release, with a deliberate train/eval isolation:

release (``data/releases/<v>/``), handed to the method subprocess
    ``dev.jsonl``          -- 410 labelled rows (train/val; pseudo-MOS + defects)
    ``dev_split.json``     -- deterministic subject-group-disjoint train/val index
    ``eval_inputs.jsonl``  -- 610 rows: ``{path, image}`` only, NO labels
    ``benchmark_meta.json``-- counts, per-defect support, source hashes

evaluation protocol dir (``evaluation/protocols/<v>/``), NOT given to methods
    ``eval_labels.jsonl``  -- 610 labelled rows, read only by the frozen evaluator

Defect labels / pseudo-MOS come from the iqa_agent benchmark; the eval split is
subject-group-disjoint from dev, so no image/subject leaks into training.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List, Optional

from . import config as C


def load_rows(path: str | Path) -> List[Dict[str, Any]]:
    p = Path(path)
    if not p.exists():
        return []
    rows: List[Dict[str, Any]] = []
    for line in p.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if line:
            rows.append(json.loads(line))
    return rows


def defect_support(rows: List[Dict[str, Any]]) -> Dict[str, int]:
    support = {d: 0 for d in C.DEFECTS}
    for r in rows:
        for d in C.DEFECTS:
            if int(bool((r.get("defects") or {}).get(d, {}).get("present", 0))):
                support[d] += 1
    return support


def _strip_labels(row: Dict[str, Any]) -> Dict[str, Any]:
    return {"path": row.get("path"), "image": row.get("image")}


def _split_dev(rows: List[Dict[str, Any]], seed: int = 7, val_frac: float = 0.25) -> Dict[str, Any]:
    """Subject-group-disjoint train/val index (deterministic)."""
    subjects = sorted({str(r.get("subject") or r.get("image") or i) for i, r in enumerate(rows)})
    import random
    rng = random.Random(seed)
    rng.shuffle(subjects)
    n_val = max(1, int(round(len(subjects) * val_frac)))
    val_subjects = set(subjects[:n_val])
    train_idx, val_idx = [], []
    for i, r in enumerate(rows):
        subj = str(r.get("subject") or r.get("image") or i)
        (val_idx if subj in val_subjects else train_idx).append(i)
    return {"seed": seed, "val_frac": val_frac, "train": train_idx, "val": val_idx,
            "n_train": len(train_idx), "n_val": len(val_idx), "group": "subject"}


def _negative_defects() -> Dict[str, Dict[str, Any]]:
    out = {d: {"present": 0, "severity": 0} for d in C.DEFECTS}
    out["white_balance"]["direction"] = "neutral"
    return out


def _koniq_rows(*, include_eval: bool = True) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """Read the real-MOS KonIQ-10k CSV into (dev_rows, eval_rows).

    ``dev`` = official *training* + *validation* images (labels visible to the
    method); ``eval`` = the official *test* images (labels frozen).  KonIQ has
    no defect taxonomy, so every row carries an all-absent 5-defect map; the
    real human MOS is the score.
    """
    import csv
    csv_path, img_dir = C.koniq_sets_csv(), C.koniq_image_dir()
    if not csv_path.exists():
        raise FileNotFoundError(f"KonIQ metadata not found at {csv_path}")
    dev: List[Dict[str, Any]] = []
    ev: List[Dict[str, Any]] = []
    with csv_path.open("r", encoding="utf-8", newline="") as fh:
        for r in csv.DictReader(fh):
            if not include_eval and r.get("set") not in ("training", "validation"):
                continue
            name = (r.get("image_name") or "").strip()
            if not name:
                continue
            ip = Path(img_dir) / name
            if not ip.exists():
                continue
            row = {
                "path": str(ip), "image": name, "subject": name,
                "score": float(r["MOS"]), "defects": _negative_defects(),
                "benchmark": "koniq10k", "set": r.get("set", ""),
            }
            (dev if r.get("set") in ("training", "validation") else ev).append(row)
    return dev, ev


def development_source_summary(seed: int = 7) -> Dict[str, Any]:
    """Preview only development aggregates, without opening holdout labels."""
    rows = _koniq_rows(include_eval=False)[0] if C.benchmark_source() == "koniq" else load_rows(C.dev_jsonl())
    if not rows:
        return {"status": "missing", "scope": "development_only"}
    split = _split_dev(rows, seed=seed)
    summaries = {}
    for name, key in (("train", "train"), ("development_test", "val")):
        selected = [rows[i] for i in split[key]]
        scores = [float(r["score"]) for r in selected if r.get("score") is not None]
        summaries[name] = {
            "count": len(selected), "defect_support": defect_support(selected),
            "score_range": [min(scores), max(scores)] if scores else None,
        }
    return {"status": "preview_not_frozen", "scope": "development_only",
            "benchmark": C.benchmark_source(), "seed": seed, "group": "subject",
            "splits": summaries, "final_labels_inspected": False,
            "label_semantics": "human MOS; no defect labels" if C.quality_only() else "pseudo-MOS + defects",
            "note": "Preview uses the default seed; the published data recipe fixes the actual split."}


def export_benchmark(tp, version: str, *, seed: int = 7) -> Dict[str, Any]:
    """Materialise the release + frozen evaluation protocol for *version*."""
    if C.benchmark_source() == "koniq":
        return _export_koniq(tp, version, seed=seed)
    release = tp.release_dir(version)
    release.mkdir(parents=True, exist_ok=True)

    dev_src, eval_src = C.dev_jsonl(), C.eval_jsonl()
    if not dev_src.exists() or not eval_src.exists():
        raise FileNotFoundError(
            f"IQA benchmark not found under {C.benchmark_dir()}; set QAA_ROOT to the workspace")

    dev_rows = load_rows(dev_src)
    eval_rows = load_rows(eval_src)
    splits = _split_dev(dev_rows, seed=seed)

    (release / "dev.jsonl").write_text(
        "\n".join(json.dumps(r, ensure_ascii=False) for r in dev_rows) + "\n", encoding="utf-8")
    (release / "eval_inputs.jsonl").write_text(
        "\n".join(json.dumps(_strip_labels(r), ensure_ascii=False) for r in eval_rows) + "\n",
        encoding="utf-8")
